  const cards = records.map(([id, date, topic, text, note, archiveSlug]) => {
    const slug = archiveSlug || date + '-' + id;
    const verdict = topic === 'claims' ? 'real-unproven' : 'real';
    if (!archiveSlug) {
      window.WP_DATA.push({ slug, d: date, k: 'n', t: text, x: note, verdict });
    }
    return { id, date, topic, text, note, verdict, slug };
  });
  cards.push(...fiction.map(([id, date, topic, text, note]) => ({
    id: 'fiction-' + id, date, topic, text, note, verdict: 'made-up',
  })));

  const originals = new Map(window.WP_CARDS.map(card => [card.id, card]));
  cards.push(...adapted.map(([id, topic, text, note]) => ({
    ...originals.get(id), topic, text, note, verdict: topic === 'claims' ? 'real-unproven' : 'real',
  })));
  window.WP_FEED_CARDS = cards;
